$Eintraege = @(
    @{ Bereich = 'Statistik »Historisches«'; Art = 'Optische Änderung'; Seit = '1.41'; Titel = '»Beste Mannschaft«: Tabelle wurde ab der 21. Saison überschrieben'
       Fehler = 'Ab der 21. Saison wurde beim Weiterrücken der Tabelle der falsche Eintrag geleert. Ein Eintrag vervielfachte sich dadurch von Saison zu Saison, bis alle 20 Zeilen dieselbe Mannschaft zeigten.'
       Korrektur = 'Beim Weiterrücken wird wieder der letzte Eintrag freigemacht; die Tabelle wird saisonweise fortgeschrieben.'
       Auswirkung = 'Wirkt ab dem nächsten Saisonwechsel. Bereits mehrfach vorhandene Einträge werden nicht berichtigt; sie rücken mit jeder weiteren Saison aus der Tabelle.'
       Haeufigkeit = '' }
    @{ Bereich = 'Statistik »Historisches«'; Art = 'Optische Änderung'; Seit = '1.41'; Titel = '»Beste Mannschaft«: zuletzt abgeschlossene Saison fehlte'
       Fehler = 'Ab der 21. Saison zeigte der Bildschirm nur 19 der 20 Einträge; die zuletzt abgeschlossene Saison fehlte.'
       Korrektur = 'Der Bildschirm zeigt wieder alle 20 Einträge.'
       Auswirkung = 'Sofort sichtbar. Reine Anzeige.'
