    @{ Bereich = 'Statistik »Historisches«'; Art = 'Optische Änderung'; Seit = '1.41'; Titel = '»Rekordaufsteiger«: Aufstiege in die Regionalliga Süd ohne Spalte'
       Fehler = 'Aufstiege in die Regionalliga Süd wurden keiner Spalte zugeordnet; die Gesamtzahl wuchs, die Spalten nicht.'
       Korrektur = 'Sie werden wie die Aufstiege in die Regionalliga Nord in der dritten Spalte geführt.'
       Auswirkung = 'Ab dem nächsten Saisonwechsel. Frühere Aufstiege in die Regionalliga Süd fehlen weiterhin in den Spalten.'
       Haeufigkeit = '' }
    @{ Bereich = 'Statistik »Historisches«'; Art = 'Optische Änderung'; Seit = '1.41'; Titel = '»Rekordabsteiger«: Spanien in der falschen Spalte'
       Fehler = 'Abstiege aus der spanischen 1. Liga wurden in der Spalte der 2. Liga geführt.'
